INSERT INTO awards ("id", "awarder_id", "name", "slug", "description", "image_src", "markers") VALUES
(1, 117474, 'Asigmatic', 'asigmatic', 'This award celebrates high voter variance, that is, images which have split the crowd. The award was originally suggested by another user, and can be read about [here](https://www.dpchallenge.com/image.php?IMAGE_ID=1000203). As opposed to many other awards, this is deterministic and is awarded to the user that received the highest vote variance amongst the submissions.', 'https://images.dpchallenge.com/images_portfolio/50000-54999/50695/120/Copyrighted_Image_Reuse_Prohibited_1000203.gif', '["Copyrighted_Image_Reuse_Prohibited_1000203", "1000203"]'),
(2, 50695, 'Posthumous Blue', 'posthumous-blue', 'Originally, this was simply my favorite shot in a challenge, but eventually I realized that most challenges don''t have one, that a Posthumous Blue is actually an image that calls to me and demands to be blue.', 'https://images.dpchallenge.com/images_portfolio/50000-54999/50695/120/Copyrighted_Image_Reuse_Prohibited_1077284.jpg', '["Copyrighted_Image_Reuse_Prohibited_1077284", "blackyak.com/dpc/bluepost", "blackyak.com/bluepost", "bluepost", "1077284"]'),
(3, 50695, 'Posthumous Red', 'posthumous-red', 'Originally, this was simply my second favorite shot in a challenge, but now indicates a fierce image that demands to be recognized above everything but the blue.', 'https://images.dpchallenge.com/images_portfolio/50000-54999/50695/120/Copyrighted_Image_Reuse_Prohibited_1077285.jpg', '["Copyrighted_Image_Reuse_Prohibited_1077285", "blackyak.com/dpc/redpost", "blackyak.com/redpost", "redpost", "1077285"]'),
(4, 50695, 'Posthumous Yellow', 'posthumous-yellow', 'Originally, this was simply my third favorite shot in a challenge, but now is an image that warrants individual recognition.', 'https://images.dpchallenge.com/images_portfolio/50000-54999/50695/120/Copyrighted_Image_Reuse_Prohibited_1077286.jpg', '["Copyrighted_Image_Reuse_Prohibited_1077286", "blackyak.com/yellowpost", "blackyak.com/dpc/yellowpost", "yellowpost", "1077286"]'),
(5, 50695, 'Posthumous Fantasy', 'posthumous-fantasy', 'An image that I would put in an exhibition if I had a gallery, or that I would print in a literary arts magazine', 'https://images.dpchallenge.com/images_portfolio/50000-54999/50695/120/Copyrighted_Image_Reuse_Prohibited_1077279.jpg', '["Copyrighted_Image_Reuse_Prohibited_1077279", "blackyak.com/dpc/artpost", "artpost", "1077279"]'),
(6, 50695, 'Posthumous Almost Blue', 'posthumous-almost-blue', 'Photos that deserved a ribbon but for some reason or other didn''t get one', 'https://images.dpchallenge.com/images_portfolio/50000-54999/50695/120/Copyrighted_Image_Reuse_Prohibited_1077283.gif', '["Copyrighted_Image_Reuse_Prohibited_1077283", "blackyak.com/dpc/almostblue", "1077283"]'),
(7, 50695, 'Posthumous Blur', 'posthumous-blur', 'Hot fuzz.', 'https://images.dpchallenge.com/images_portfolio/50000-54999/50695/120/Copyrighted_Image_Reuse_Prohibited_1077281.jpg', '["Copyrighted_Image_Reuse_Prohibited_1077281", "blackyak.com/dpc/blurpost", "1077281"]'),
(8, 50695, 'Posthumous Boo', 'posthumous-boo', 'So good it''s scary', 'https://images.dpchallenge.com/images_portfolio/50000-54999/50695/120/Copyrighted_Image_Reuse_Prohibited_1077280.jpg', '["Copyrighted_Image_Reuse_Prohibited_1077280", "blackyak.com/dpc/boopost", "1077280"]'),
(9, 103142, 'Bluebird of Happiness', 'bluebird-of-happiness', 'I''ve wanted to create an award like those in the posthumous thread. So this is the "bluebird of happiness" award. If goes to pictures that I think are wonderful, help me see things in a different way, or ones that simply make me smile.', 'https://images.dpchallenge.com/images_portfolio/100000-104999/103142/120/Copyrighted_Image_Reuse_Prohibited_811107.jpg', '["Copyrighted_Image_Reuse_Prohibited_811107", "811107"]'),
(10, 32011, 'MUAIMHO', 'muaimho', 'Most under-appreciated in my honest opinion', 'https://images.dpchallenge.com/images_portfolio/30000-34999/32011/120/Copyrighted_Image_Reuse_Prohibited_858386.png', '["Copyrighted_Image_Reuse_Prohibited_", "858386"]'),
(11, 114285, 'Verineat image', 'verineat-image', 'For those images that make me sigh!', 'https://images.dpchallenge.com/images_portfolio/110000-114999/114285/120/Copyrighted_Image_Reuse_Prohibited_1070026.jpg', '["Copyrighted_Image_Reuse_Prohibited_1070026", "Copyrighted_Image_Reuse_Prohibited_1014169", "1070026", "1014169"]'),
(12, 82985, 'Post Lumy Award', 'post-lumy-award', 'Nominations go to LUMINOUS images (often overlooked). I can''t limit choices to 3 "ribbons" so this "Nomination" approach lets me recognize more images', 'https://images.dpchallenge.com/images_portfolio/80000-84999/82985/120/Copyrighted_Image_Reuse_Prohibited_677021.jpg', '["Copyrighted_Image_Reuse_Prohibited_677021", "677021"]'),
