(15, 41337, 'yanko blue', 'yanko-blue', 'Awarded to photos that best exemplifies photography as an art form in a challenge.', 'https://images.dpchallenge.com/images_portfolio/40000-44999/41337/120/Copyrighted_Image_Reuse_Prohibited_657188.gif', '["Copyrighted_Image_Reuse_Prohibited_657188", "657188"]'),
