(23, 38032, 'Breaking Rad', 'breaking-rad', '', 'https://images.dpchallenge.com/images_portfolio/35000-39999/38032/120/Copyrighted_Image_Reuse_Prohibited_1174300.png', '["Copyrighted_Image_Reuse_Prohibited_1174300", "1174300"]'),
(24, 100393, 'Unconventional Eye', 'unconventional-eye', 'Worth a Longer Look?This award is given to an image that I think was taken with an unconventional eye and has more to offer than its final score might suggest.I humbly invite interested viewers to take a longer look and see if the image grows on them at all.', 'https://images.dpchallenge.com/images_portfolio/100000-104999/100393/120/Copyrighted_Image_Reuse_Prohibited_859062.jpg', '["Copyrighted_Image_Reuse_Prohibited_859062", "859062"]'),
(25, 100393, 'Forward Movement', 'forward-movement', 'This is an ''icon'' image to replace my ''Longer Look'' award. This award the ''Forward Movement'' is given to the image that I think best takes the DPC community portfolio of images forward.This image is taken from the ''In the Style of Nixter'': One of the best challenges we have had for interesting images.', 'https://images.dpchallenge.com/images_portfolio/100000-104999/100393/120/Copyrighted_Image_Reuse_Prohibited_1051747.jpg', '["Copyrighted_Image_Reuse_Prohibited_1051747", "1051747"]'),
(26, 54645, 'Sterling Sturgeon', 'sterling-sturgeon', 'Going forward, I''ll post the recipients here as a pseudo-gallery as well as the posthumous thread.', 'https://images.dpchallenge.com/images_portfolio/50000-54999/54645/120/Copyrighted_Image_Reuse_Prohibited_963227.jpg', '["Copyrighted_Image_Reuse_Prohibited_963227", "963227"]'),
(27, 30364, 'The Thumb', 'the-thumb', '', 'https://images.dpchallenge.com/images_portfolio/30000-34999/30364/120/Copyrighted_Image_Reuse_Prohibited_800078.jpg', '["Copyrighted_Image_Reuse_Prohibited_800078", "800078"]'),
