(32, 53572, 'X Yellow', 'x-yellow', 'The x prize is back, ''cause I''m back. These are for the lowest placers of my highest scores: those who wuz robbed...', 'https://images.dpchallenge.com/images_portfolio/50000-54999/53572/120/Copyrighted_Image_Reuse_Prohibited_657243.jpg', '["Copyrighted_Image_Reuse_Prohibited_657243", "657243"]'),
(33, 3724, 'undie award', 'undie-award', 'An award created at the request of Posthumous "undie award" - achievement recognition icon for Posthumous Ribbons thread or when ever I feel like giving it.The award may be given during voting or after a challenge is completed to insure that my highest votes coincide with challenge submissions whose over all score is 5 and below, or under 50%.', 'https://images.dpchallenge.com/images_portfolio/0-4999/3724/120/Copyrighted_Image_Reuse_Prohibited_753886.jpg', '["Copyrighted_Image_Reuse_Prohibited_753886", "753886"]'),
